/** Source: roulette.c → SpriteCB_Shroomish */
export const SpriteCB_Shroomish: SpriteCallback = (sprite, rt) => {
  if (sprite.data[7] == 0)
      {
           
           
          if (!sRoulette.ball.data[0])
          {
              if (sRoulette.ball.data[3] != sRouletteTables[sRoulette.tableId].shroomish.startAngle)
                  return;
          }
          else
          {
              if (sRoulette.ball.data[3] != sRouletteTables[sRoulette.tableId].shroomish.startAngle + 180)
                  return;
          }

          sprite.invisible = false;
          sprite.data[7]++;
          PlaySE(SE_FALL);
          sRoulette.shroomishShadowTimer = 1;
          sRoulette.shroomishShadowAlpha = sShroomishShadowAlphas[0];
      }
      else
      {
          sRoulette.shroomishShadowAlpha = sShroomishShadowAlphas[(sRoulette.shroomishShadowTimer - 1) / 2];
          if (sRoulette.shroomishShadowTimer < 19)
              sRoulette.shroomishShadowTimer++;

           
           
           
          if (!sRoulette.ball.data[0])
          {
              if (sRoulette.ball.data[3] != sRouletteTables[sRoulette.tableId].shroomish.dropAngle)
                  return;
          }
          else
          {
              if (sRoulette.ball.data[3] != sRouletteTables[sRoulette.tableId].shroomish.dropAngle + 180)
                  return;
          }

          rt.setSpriteCallback(sprite.data[4], SpriteCB_ShroomishFall);
          _gs(rt, sprite.data[4]).invisible = false;
          sprite.callback  = SpriteCallbackDummy;
          sprite.data[7] = 0;
      }
};

