/** Source: roulette.c → SpriteCB_Taillow_FlyIn */
export const SpriteCB_Taillow_FlyIn: SpriteCallback = (sprite, rt) => {
  let xMoveOffsets: any = [-1, 1];
      const yMoveOffsets: any = [
          [2, 0],
          [2, 0],
          [2, -1],
          [2, -1],
          [2, -1],
          [2, -1],
          [2, -2],
          [2, -2],
      ];

      if (sprite.data[1]-- > 7)
      {
          sprite.x += xMoveOffsets[sRoulette.ball.data[0]] * 2;
          if (IsSEPlaying())
          {
              let pan = -((116 - sprite.x) / 2);
              m4aMPlayPanpotControl(gMPlayInfo_SE1, TRACKS_ALL, pan);
              m4aMPlayPanpotControl(gMPlayInfo_SE2, TRACKS_ALL, pan);
          }
      }
      else
      {
          if (sprite.data[1] >= 0)
          {
              sprite.x += xMoveOffsets[sRoulette.ball.data[0]] * yMoveOffsets[7 - sprite.data[1]][0];
              sprite.y += yMoveOffsets[7 - sprite.data[1]][1];
          }
          else
          {
              m4aSongNumStartOrChange(SE_TAILLOW_WING_FLAP);
              if (sRoulette.ball.data[0] == 0)
                  PlayCry_Normal(SPECIES_TAILLOW, 63);
              else
                  PlayCry_Normal(SPECIES_TAILLOW, -63);
              rt.StartSpriteAnim(sprite.spriteId, sRoulette.ball.data[0] + 2);
              sprite.data[1] = 45;
              sprite.callback = SpriteCB_Taillow_PickUpBall;
          }
      }
};

