/** Source: roulette.c → Task_InitBallRoll */
export const Task_InitBallRoll: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let randTravelMod = 0;
      let randTravelDist = 0;
      let startAngleId = 0;
      let travelDist = 0;
      let rand = 0;
      let randmod = 0;
      let startAngles: any = [0, 180, 90, 270];  

      rand = Math.floor(Math.random() * 0x10000);
      randmod = rand % 100;
      sRoulette.curBallSpriteId = task.data[6];
       
      sRoulette.ballState = sRoulette.hitSlot = sRoulette.stuckHitSlot = 0;
      randTravelMod = GetRandomForBallTravelDistance(task.data[8], rand);
      randTravelDist = (rand % randTravelMod) - (randTravelMod / 2);

      if (gLocalTime.hours < 13)
          startAngleId = 0;
      else
          startAngleId = 1;

      if (randmod < 80)
          startAngleId *= 2;
      else
          startAngleId = (1 - startAngleId) * 2;

      sRoulette.ballTravelDist = travelDist = sRouletteTables[sRoulette.tableId].baseTravelDist + randTravelDist;

      travelDist = S16TOPOSFLOAT(travelDist) / 5.0;
      sRoulette.ballTravelDistFast = travelDist * 3;
      sRoulette.ballTravelDistSlow = sRoulette.ballTravelDistMed = travelDist;

      sRoulette.ballAngle = S16TOPOSFLOAT(startAngles[(rand & 1) + startAngleId]);
      sRoulette.ballAngleSpeed = S16TOPOSFLOAT(sRouletteTables[sRoulette.tableId].ballSpeed);
      sRoulette.ballAngleAccel = ((sRoulette.ballAngleSpeed * 0.5) - sRoulette.ballAngleSpeed) / S16TOPOSFLOAT(sRoulette.ballTravelDistFast);
      sRoulette.ballDistToCenter = 68.0;
      sRoulette.ballFallAccel = 0.0;
      sRoulette.ballFallSpeed = -(8.0 / S16TOPOSFLOAT(sRoulette.ballTravelDistFast));
      sRoulette.varA0 = 36.0;
      task.func = (t) => Task_RollBall(t, rt);
};

