/** Source: roulette.c → Task_RecordBallHit */
export const Task_RecordBallHit: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (sRoulette.ballState != BALL_STATE_ROLLING)
      {
           
          if (sRoulette.ballStuck)
          {
              if (sRoulette.ballUnstuck)
              {
                  sRoulette.ballUnstuck = false;
                  sRoulette.ballStuck = false;
              }
          }
          else
          {
              if (task.data[1] == 0)
              {
                  let won = IsHitInBetSelection(RecordHit(taskId, sRoulette.hitSlot), sRoulette.betSelection[sRoulette.curBallNum]);
                  task.data[5] = won;
                  if (won == true)
                      RouletteFlash_Enable(sRoulette.flashUtil, F_FLASH_OUTER_EDGES);
              }
              if (task.data[1] <= 60)
              {
                  if (JOY_NEW(A_BUTTON))
                      task.data[1] = 60;
                  task.data[1]++;
              }
              else
              {
                  DrawGridBackground(sRoulette.betSelection[sRoulette.curBallNum]);
                  ShowHideGridIcons(false, task.data[12]);
                  ShowHideGridBalls(false, task.data[6] - 1);
                  task.data[1] = 32;
                  task.func = (t) => Task_SlideGridOnscreen(t, rt);
              }
          }
      }
};

