/** Source: roulette.c → Task_WaitForNextTask */
export const Task_WaitForNextTask: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (sRoulette.taskWaitDelay == 0 || JOY_NEW(sRoulette.taskWaitKey))
      {
          task.func = (t) => sRoulette(t, rt).nextTask;
          if (sRoulette.taskWaitKey > 0)
              PlaySE(SE_SELECT);
          sRoulette.nextTask = null;
          sRoulette.taskWaitKey = 0;
          sRoulette.taskWaitDelay = 0;
      }
      if (sRoulette.taskWaitDelay != NO_DELAY)
          sRoulette.taskWaitDelay--;
};

/** Source: roulette.c → Task_ShowMinBetYesNo */
export const Task_ShowMinBetYesNo: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  DisplayYesNoMenuDefaultYes();
      DoYesNoFuncWithChoice(taskId, sYesNoTable_AcceptMinBet);
};

/** Source: roulette.c → Task_FadeToRouletteGame */
export const Task_FadeToRouletteGame: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (!rt.gPaletteFade.active)
      {
          rt.SetVBlankCallback(VBlankCB);
          rt.SetMainCallback2(CB2_LoadRoulette);
          rt.DestroyTask(taskId);
      }
};

/** Source: roulette.c → Task_AcceptMinBet */
export const Task_AcceptMinBet: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  ClearStdWindowAndFrame(0, true);
      HideCoinsWindow();
      FreeAllWindowBuffers();
      rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0, 16, "RGB_BLACK");
      rt.gPaletteFade.delayCounter = rt.gPaletteFade.multipurpose2;
      UpdatePaletteFade();
      task.func = (t) => Task_FadeToRouletteGame(t, rt);
};

/** Source: roulette.c → Task_DeclineMinBet */
export const Task_DeclineMinBet: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  ClearStdWindowAndFrame(0, false);
      HideCoinsWindow();
      UnlockPlayerFieldControls();
      rt.DestroyTask(taskId);
};

/** Source: roulette.c → Task_NotEnoughForMinBet */
export const Task_NotEnoughForMinBet: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  task.data[0]++;
      if (JOY_NEW(A_BUTTON | B_BUTTON))
      {
          gSpecialVar_0x8004 = 1;
          HideCoinsWindow();
          ClearStdWindowAndFrame(0, true);
          UnlockPlayerFieldControls();
          rt.DestroyTask(taskId);
      }
};

/** Source: roulette.c → Task_PrintMinBet */
export const Task_PrintMinBet: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (JOY_NEW(A_BUTTON | B_BUTTON))
      {
          let minBet = sTableMinBets[GET_MIN_BET_ID(gSpecialVar_0x8004)];
          ConvertIntToDecimalStringN(gStringVar1, minBet, STR_CONV_MODE_LEADING_ZEROS, 1);
          StringExpandPlaceholders(gStringVar4, Roulette_Text_PlayMinimumWagerIsX);
          DrawStdWindowFrame(0, false);
          AddTextPrinterParameterized(0, FONT_NORMAL, gStringVar4, 0, 1, TEXT_SKIP_DRAW, null);
          CopyWindowToVram(0, COPYWIN_FULL);
          task.func = (t) => Task_ShowMinBetYesNo(t, rt);
      }
};

/** Source: roulette.c → Task_PrintRouletteEntryMsg */
export const Task_PrintRouletteEntryMsg: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let minBet = 0;
      PrintCoinsString(task.data[13]);
      minBet = sTableMinBets[GET_MIN_BET_ID(gSpecialVar_0x8004)];
      ConvertIntToDecimalStringN(gStringVar1, minBet, STR_CONV_MODE_LEADING_ZEROS, 1);

      if (task.data[13] >= minBet)
      {
          if ((gSpecialVar_0x8004 & ROULETTE_SPECIAL_RATE) && (gSpecialVar_0x8004 & 1))
          {
               
              DrawStdWindowFrame(0, false);
              AddTextPrinterParameterized(0, FONT_NORMAL, Roulette_Text_SpecialRateTable, 0, 1, TEXT_SKIP_DRAW, null);
              CopyWindowToVram(0, COPYWIN_FULL);
              task.func = (t) => Task_PrintMinBet(t, rt);
          }
          else
          {
               
              StringExpandPlaceholders(gStringVar4, Roulette_Text_PlayMinimumWagerIsX);
              DrawStdWindowFrame(0, false);
              AddTextPrinterParameterized(0, FONT_NORMAL, gStringVar4, 0, 1, TEXT_SKIP_DRAW, null);
              CopyWindowToVram(0, COPYWIN_FULL);
              task.func = (t) => Task_ShowMinBetYesNo(t, rt);
          }
      }
      else
      {
           
          StringExpandPlaceholders(gStringVar4, Roulette_Text_NotEnoughCoins);
          DrawStdWindowFrame(0, false);
          AddTextPrinterParameterized(0, FONT_NORMAL, gStringVar4, 0, 1, TEXT_SKIP_DRAW, null);
          CopyWindowToVram(0, COPYWIN_FULL);
          task.func = (t) => Task_NotEnoughForMinBet(t, rt);
          task.data[13] = 0;
          task.data[0] = 0;
      }
};

/** Source: roulette.c → CB2_Roulette */
export const CB2_Roulette: CB2Callback = (rt) => {
  RunTasks();
      AnimateSprites();
      BuildOamBuffer();
      if (sRoulette.flashUtil.enabled)
          RouletteFlash_Run(sRoulette.flashUtil);
};

/** Source: roulette.c → CB2_LoadRoulette */
export const CB2_LoadRoulette: CB2Callback = (rt) => {
  let taskId = 0;

      switch (gMain.state)
      {
      case 0:
          rt.SetVBlankCallback(VBlankCB);
          ScanlineEffect_Stop();
          SetVBlankHBlankCallbacksToNull();
          ResetVramOamAndBgCntRegs();
          ResetAllBgsCoordinates();
          break;
      case 1:
          InitRouletteBgAndWindows();
          DeactivateAllTextPrinters();
          rt.SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_NONE |
                                       BLDCNT_TGT2_BG2 |
                                       BLDCNT_TGT2_BD);
          rt.SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(10, 6));
          break;
      case 2:
          ResetPaletteFade();
          rt.ResetSpriteData();
          ResetTasks();
          ResetTempTileDataBuffers();
          break;
      case 3:
          LoadPalette(sWheel_Pal, BG_PLTT_ID(0), 14 * PLTT_SIZE_4BPP);
          DecompressAndCopyTileDataToVram(1, gRouletteMenu_Gfx, 0, 0, 0);
          DecompressAndCopyTileDataToVram(2, gRouletteWheel_Gfx, 0, 0, 0);
          break;
      case 4:
          if (FreeTempTileDataBuffersIfPossible())
              return;

          InitRouletteTableData();
          CopyToBgTilemapBuffer(2, sWheel_Tilemap, 0, 0);
          break;
      case 5:
          LoadOrFreeMiscSpritePalettesAndSheets(false);
          CreateWheelBallSprites();
          CreateWheelCenterSprite();
          CreateInterfaceSprites();
          CreateGridSprites();
          CreateGridBallSprites();
          CreateWheelIconSprites();
          break;
      case 6:
          AnimateSprites();
          BuildOamBuffer();
          SetCreditDigits(GetCoins());
          SetBallCounterNumLeft(BALLS_PER_ROUND);
          SetMultiplierSprite(SELECTION_NONE);
          DrawGridBackground(SELECTION_NONE);
          DrawStdWindowFrame(sTextWindowId, false);
          AddTextPrinterParameterized(sTextWindowId, FONT_NORMAL, Roulette_Text_ControlsInstruction, 0, 1, TEXT_SKIP_DRAW, null);
          CopyWindowToVram(sTextWindowId, COPYWIN_FULL);
          gSpriteCoordOffsetX = -60;
          gSpriteCoordOffsetY = 0;
          break;
      case 7:
          rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0 |
                                        DISPCNT_OBJ_1D_MAP |
                                        DISPCNT_OBJ_ON);
          CopyBgTilemapBufferToVram(1);
          CopyBgTilemapBufferToVram(2);
          ShowBg(0);
          ShowBg(1);
          ShowBg(2);
          break;
      case 8:
          EnableInterrupts(INTR_FLAG_VBLANK);
          rt.SetVBlankCallback(VBlankCB);
          BeginHardwarePaletteFade(0xFF, 0, 16, 0, 1);
          taskId = sRoulette.playTaskId = rt.CreateTask((t) => Task_StartPlaying(t, rt), 0);
          task.data[6] = BALLS_PER_ROUND;
          task.data[13] = GetCoins();
          AlertTVThatPlayerPlayedRoulette(GetCoins());
          sRoulette.spinTaskId = rt.CreateTask((t) => Task_SpinWheel(t, rt), 1);
          rt.SetMainCallback2(CB2_Roulette);
          return;
      }
      gMain.state++;
};

/** ⚠️ Generic patch (post-transpile-patches.mjs) — VBlankCB no-op.
 *  Notre runtime call TransferPlttBuffer auto si vblankCallback non-null,
 *  donc le scene-side VBlankCB est essentiellement un marqueur "transfer ON". */
const VBlankCB: () => void = () => { /* no-op */ };
